/*
 * A372727  Triangle read by rows: T(n, k) = n if k = 0, otherwise n -
 *          k*floor(n/k). The binary modulo operation.
 * https://oeis.org/A372727
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn, tabl
 * Formula:   a(n) = T(r,k) where r = ⌈(-1 + √(8n+1))/2⌉ - 1, k = n -
 *            r(r+1)/2. T(r,0) = r, T(r,k) = r - k * ⌊r/k⌋ for k>0. This is
 *            the triangle read by rows generated by the binary “mod”
 *            operation
 * Range:     u8 n <= 9851, u16 n <= 9851, u32 n <= 9851, u64 n <= 9851,
 *            u128 n <= 9851, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdint.h>
#include <math.h>

seq_t a(idx_t n)
{
    /* Convert the index to the corresponding row r and column k. */
    long double d = sqrtl((long double)8.0L * n + 1.0L);
    unsigned long long t = (unsigned long long)((d - 1.0L) / 2.0L) + 1U;
    idx_t r = (idx_t)(t - 1U);

    /* prefix sum of lengths of rows up to r-1: r*(r+1)/2        */
    idx_t pref = (idx_t)(((seq_t)r * (seq_t)(r + 1)) / 2);

    /* position k within the current row */
    idx_t k = n - pref;

    /* compute T(r,k) */
    if (k == 0)
        return (seq_t)r;

    seq_t floor_div = (seq_t)r / (seq_t)k;
    seq_t result   = (seq_t)r - (seq_t)k * floor_div;
    return result;
}
